/**
 * Replaces the store's look: its theme, and the headline font and corners it uses in place of the theme's.
 */
export type StoreThemeBody = {
    theme: StoreTheme;
    /**
     * Left out or null for the theme's own.
     */
    heading_font?: 'instrument-serif' | 'fraunces' | 'geist' | 'space-grotesk' | 'playfair' | 'archivo' | null;
    /**
     * Left out or null for the theme's own.
     */
    corners?: 'sharp' | 'soft' | 'round' | null;
};

/**
 * Turns the banner on or off and replaces its messages, in order. An empty list hides it too.
 */
export type AnnouncementsBody = {
    /**
     * Show the banner, or hide it and keep its messages.
     */
    announcements_enabled: boolean;
    announcements: Array<string>;
};

/**
 * Replaces the seller's details shown in the footer, contact page and legal pages. Empty strings clear a field.
 */
export type BusinessDetailsBody = {
    business_name: string;
    business_id: string;
    business_address: string;
    business_email: string;
    business_phone: string;
};

/**
 * Replaces the logo in the store's header.
 */
export type StoreLogoBody = {
    /**
     * An uploaded image's https URL; null or left out goes back to the built-in mark.
     */
    logo_url?: string | null;
};

/**
 * Replaces what delivery costs: the flat price, and the subtotal (after any discount code) or item count from which orders ship free.
 */
export type ShippingBody = {
    /**
     * Cents, 0 to 100000; 0 ships every order free.
     */
    flat: number;
    /**
     * Cents, 1 to 10000000; left out or null: no amount rule.
     */
    free_from?: number | null;
    /**
     * Items, 1 to 100; left out or null: no item rule.
     */
    free_items?: number | null;
};

/**
 * Replaces the referral programme: whether it runs, the friend's discount, the referrer's credit and when it's paid, and the limits on credit. Referrals already made keep their rule.
 */
export type ReferralBody = {
    /**
     * Run the programme, or pause it and keep its rule.
     */
    enabled: boolean;
    friend_kind: ReferralFriendKind;
    /**
     * Cents, 1 to 100000, or a percent, 1 to 50.
     */
    friend_value: number;
    /**
     * Cents, 1 to 100000; left out or null: no minimum.
     */
    friend_min?: number | null;
    /**
     * Cents, 1 to 100000.
     */
    reward: number;
    /**
     * Days, 0 to 365; 0 pays as soon as the order is paid.
     */
    pay_after_days: number;
    custom_prints: boolean;
    /**
     * Referrals, 1 to 100; left out or null: no limit.
     */
    monthly_cap?: number | null;
    /**
     * Percent, 1 to 100.
     */
    credit_max_percent: number;
    /**
     * Months, 1 to 60; left out or null: credit never lapses.
     */
    credit_expiry_months?: number | null;
};

export type ReferralFriendKind = 'amount' | 'percent';

